import networkx as nx
from collections import defaultdict

edges = [(0, 5), (0, 7), (0, 13), (1, 8), (1, 10), (1, 13), (2, 4), (2, 5), (2, 12), (3, 4), (3, 6), (3, 7), (4, 10), (5, 11), (6, 11), (6, 13), (7, 9), (8, 11), (8, 12), (9, 10), (9, 12)]

G = nx.Graph()
G.add_edges_from(edges)

print(f"Number of vertices: {G.number_of_nodes()}")
print(f"Number of edges: {G.number_of_edges()}")
print(f"Degree sequence: {sorted(dict(G.degree()).values())}")

# Check girth
try:
    girth = nx.girth(G)
    print(f"Girth: {girth}")
except nx.NetworkXNoCycle:
    print("No cycles (tree)")
except Exception as e:
    print(f"Error: {e}")

# Let's also find all cycles up to length 6 to verify
cycles = list(nx.simple_cycles(G))
print(f"Number of cycles found: {len(cycles)}")
for c in cycles:
    if len(c) <= 6:
        print(f"  Cycle of length {len(c)}: {c}")

# Verify 3-regular
degrees = dict(G.degree())
print(f"All degrees: {sorted(degrees.values())}")
print(f"Min degree: {min(degrees.values())}, Max degree: {max(degrees.values())}")

# Check for any self-loops or duplicate edges
print(f"Has self loops: {any(u==v for u,v in edges)}")
print(f"All edges unique: {len(set(edges)) == len(edges)}")
print(f"All vertices 0-13 present: {set(range(14)) == set(degrees.keys())}")

# Let's also verify no 3-cycles or 4-cycles manually
def has_short_cycle(edges, n, max_len):
    adj = defaultdict(set)
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_len:
                        return True, (start, u, v, cycle_len)
    return False, None

print(f"Has cycle <=4: {has_short_cycle(edges, 14, 4)}")
print(f"Has cycle <=5: {has_short_cycle(edges, 14, 5)}")

# Let's find the actual shortest cycle
def shortest_cycle(edges, n):
    adj = defaultdict(set)
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

print(f"Shortest cycle length: {shortest_cycle(edges, 14)}")
